	sections = {
		{
			title = "Summary",
			text = [=[Shadowfang Keep stands on a dark hill in southern {link:silverpine-forest}Silverpine Forest{/link}, above the hamlet of {link:pyrewood-village}Pyrewood{/link}. It was once the seat of the noble {link:baron-silverlaine}Baron Silverlaine{/link}. Now it is the lair of {link:archmage-arugal}Archmage Arugal{/link} and of the worgen he calls his children. Wolf-men prowl its halls, worgs howl in its courtyards, and the dead of the baron's household still walk the rooms where they were slain.]=],
		},
		{
			title = "Origins",
			text = [=[In the {link:third-war}Third War{/link}, the wizards of the {link:kirin-tor}Kirin Tor{/link} fought the {link:scourge}Scourge{/link} in the north. Every wizard who fell soon rose again to fight for the enemy, and the Scourge only grew. {link:archmage-arugal}Arugal{/link} would not accept it. Against the counsel of his peers, he called upon beings from beyond the world to fill the thinning ranks of {link:dalaran}Dalaran{/link}. What answered his summons were the {red:worgen}worgen{/red}. The ravenous wolf-men tore through the undead, then turned upon the wizards themselves. They laid siege to the keep of {link:baron-silverlaine}Baron Silverlaine{/link}, and it fell into shadow and ruin. Maddened by guilt, Arugal took the worgen for his own children. He withdrew into the fallen keep and gave it a new name: Shadowfang.]=],
		},
		{
			title = "The Present Day",
			text = [=[The {link:forsaken}Forsaken{/link} cannot hold {link:silverpine-forest}Silverpine{/link} while {link:archmage-arugal}Arugal{/link} lives, and they have sworn to see him dead. {link:high-executor-hadrec}High Executor Hadrec{/link} sent two Deathstalkers into the keep to learn its secrets. They did not return. The {link:kirin-tor}Kirin Tor{/link} have sent their own agent as well, and he fared no better. Both now wait in cells near the gate. {link:keeper-bel-dugur}Keeper Bel'dugur{/link} of the {link:undercity}Undercity{/link} wants a book that lies somewhere in the keep, the work of a mage of {link:dalaran}Dalaran{/link} named Ur, who studied other worlds. At the {link:the-sepulcher}Sepulcher{/link}, a dead archmage now claims that Arugal never made the worgen at all.]=],
		},
		{
			title = "Within the Keep",
			text = [=[• {b}The Cells.{/b} Near the entrance, the worgen {link:rethilgore}Rethilgore{/link} keeps his prisoners locked away.
• {b}The Courtyard.{/b} Beyond a sealed door lies the inner yard, where the keep's dead soldiers and {link:archmage-arugal}Arugal{/link}'s worgen keep watch together.
• {b}The Halls of the Household.{/b} {link:razorclaw-the-butcher}Razorclaw the Butcher{/link} works in the kitchens. {link:baron-silverlaine}Baron Silverlaine{/link}'s ghost haunts the dining hall, and {link:commander-springvale}Commander Springvale{/link} holds a council room with his dead officers.
• {b}The Heights.{/b} {link:odo-the-blindwatcher}Odo the Blindwatcher{/link} keeps his lookout high on the walls. {link:wolf-master-nandos}Wolf Master Nandos{/link} runs his pack across the upper courtyard, and {link:fenrus-the-devourer}Fenrus the Devourer{/link} guards the chambers of his master.
• {b}Arugal's Refuge.{/b} At the top of the keep, the archmage waits among his servants.]=],
		},
	},
})

